class Solution {
public:
    bool canDivideIntoSubsequences(vector<int>& nums, int k) {
        int max_freq = 0;
        int curr_freq = 0;
        int prev = -1;
        for (int x : nums) {
            if (x == prev) {
                curr_freq++;
            } else {
                curr_freq = 1;
                prev = x;
            }
            max_freq = max(max_freq, curr_freq);
        }
        return nums.size() >= (long long)max_freq * k;
    }
};

class Solution {
    public boolean canDivideIntoSubsequences(int[] nums, int k) {
        int maxFreq = 0;
        int currFreq = 0;
        int prev = -1;
        for (int x : nums) {
            if (x == prev) {
                currFreq++;
            } else {
                currFreq = 1;
                prev = x;
            }
            maxFreq = Math.max(maxFreq, currFreq);
        }
        return nums.length >= (long) maxFreq * k;
    }
}

var canDivideIntoSubsequences = function(nums, k) {
    let maxFreq = 0;
    let currFreq = 0;
    let prev = -1;
    for (const x of nums) {
        if (x === prev) {
            currFreq++;
        } else {
            currFreq = 1;
            prev = x;
        }
        if (currFreq > maxFreq) maxFreq = currFreq;
    }
    return nums.length >= maxFreq * k;
};
